  1215  void Mac::HandleTimer(void)
  1216  {
  1217      switch (mOperation)
  1218      {
  1219      case kOperationActiveScan:
  1220          PerformActiveScan();
  1221          break;
  1222
  1223      case kOperationWaitingForData:
  1224          otLogDebgMac("Data poll timeout");
  1225          FinishOperation();
  1226          GetNetif().GetMeshForwarder().GetDataPollManager().HandlePollTimeout();
  1227          PerformNextOperation();
  1228          break;
  1229
  1230  #if OPENTHREAD_CONFIG_STAY_AWAKE_BETWEEN_FRAGMENTS
  1231      case kOperationIdle:
  1232          if (mDelayingSleep)
  1233          {
  1234              otLogDebgMac("Sleep delay timeout expired");
  1235              mDelayingSleep = false;
  1236              UpdateIdleMode();
  1237          }
  1238
  1239          break;
  1240  #endif
  1241
  1242      default:
  1243          assert(false);
  1244          break;
  1245      }
  1246  }
