  1248  otError Mac::ProcessReceiveSecurity(Frame &aFrame, const Address &aSrcAddr, Neighbor *aNeighbor)
  1249  {
  1250      KeyManager &      keyManager = GetNetif().GetKeyManager();
  1251      otError           error      = OT_ERROR_NONE;
  1252      uint8_t           securityLevel;
  1253      uint8_t           keyIdMode;
  1254      uint32_t          frameCounter;
  1255      uint8_t           nonce[kNonceSize];
  1256      uint8_t           tag[Frame::kMaxMicSize];
  1257      uint8_t           tagLength;
  1258      uint8_t           keyid;
  1259      uint32_t          keySequence = 0;
  1260      const uint8_t *   macKey;
  1261      const ExtAddress *extAddress;
  1262      Crypto::AesCcm    aesCcm;
  1263
  1264      if (aFrame.GetSecurityEnabled() == false)
  1265      {
  1266          ExitNow();
  1267      }
  1268
  1269      aFrame.GetSecurityLevel(securityLevel);
  1270      aFrame.GetFrameCounter(frameCounter);
  1271      otLogDebgMac("Frame counter %u", frameCounter);
  1272
  1273      aFrame.GetKeyIdMode(keyIdMode);
  1274
  1275      switch (keyIdMode)
  1276      {
  1277      case Frame::kKeyIdMode0:
  1278          VerifyOrExit((macKey = keyManager.GetKek()) != NULL, error = OT_ERROR_SECURITY);
  1279          extAddress = &aSrcAddr.GetExtended();
  1280          break;
  1281
  1282      case Frame::kKeyIdMode1:
  1283          VerifyOrExit(aNeighbor != NULL, error = OT_ERROR_SECURITY);
  1284
  1285          aFrame.GetKeyId(keyid);
  1286          keyid--;
  1287
  1288          if (keyid == (keyManager.GetCurrentKeySequence() & 0x7f))
  1289          {
  1290              // same key index
  1291              keySequence = keyManager.GetCurrentKeySequence();
  1292              macKey      = keyManager.GetCurrentMacKey();
  1293          }
  1294          else if (keyid == ((keyManager.GetCurrentKeySequence() - 1) & 0x7f))
  1295          {
  1295          {
  1296              // previous key index
  1297              keySequence = keyManager.GetCurrentKeySequence() - 1;
  1298              macKey      = keyManager.GetTemporaryMacKey(keySequence);
  1299          }
  1300          else if (keyid == ((keyManager.GetCurrentKeySequence() + 1) & 0x7f))
  1301          {
  1302              // next key index
  1303              keySequence = keyManager.GetCurrentKeySequence() + 1;
  1304              macKey      = keyManager.GetTemporaryMacKey(keySequence);
  1305          }
  1306          else
  1307          {
  1308              ExitNow(error = OT_ERROR_SECURITY);
  1309          }
  1310
  1311          // If the frame is from a neighbor not in valid state (e.g., it is from a child being
  1312          // restored), skip the key sequence and frame counter checks but continue to verify
  1313          // the tag/MIC. Such a frame is later filtered in `RxDoneTask` which only allows MAC
  1314          // Data Request frames from a child being restored.
  1315
  1316          if (aNeighbor->GetState() == Neighbor::kStateValid)
  1317          {
  1318              if (keySequence < aNeighbor->GetKeySequence())
  1319              {
  1320                  ExitNow(error = OT_ERROR_SECURITY);
  1321              }
  1322              else if (keySequence == aNeighbor->GetKeySequence())
  1323              {
  1324                  if ((frameCounter + 1) < aNeighbor->GetLinkFrameCounter())
  1325                  {
  1326                      ExitNow(error = OT_ERROR_SECURITY);
  1327                  }
  1328                  else if ((frameCounter + 1) == aNeighbor->GetLinkFrameCounter())
  1329                  {
  1330                      // drop duplicated frames
  1331                      ExitNow(error = OT_ERROR_DUPLICATED);
  1332                  }
  1333              }
  1334          }
  1335
  1336          extAddress = &aSrcAddr.GetExtended();
  1337
  1338          break;
  1339
  1340      case Frame::kKeyIdMode2:
  1341          macKey     = sMode2Key;
  1342          extAddress = static_cast<const ExtAddress *>(&sMode2ExtAddress);
  1343          break;
  1344
  1345      default:
  1346          ExitNow(error = OT_ERROR_SECURITY);
  1347          break;
  1348      }
  1349
  1350      GenerateNonce(*extAddress, frameCounter, securityLevel, nonce);
  1351      tagLength = aFrame.GetFooterLength() - Frame::kFcsSize;
  1352
  1353      aesCcm.SetKey(macKey, 16);
  1354
  1355      error = aesCcm.Init(aFrame.GetHeaderLength(), aFrame.GetPayloadLength(), tagLength, nonce, sizeof(nonce));
  1356      VerifyOrExit(error == OT_ERROR_NONE, error = OT_ERROR_SECURITY);
  1357
  1358      aesCcm.Header(aFrame.GetHeader(), aFrame.GetHeaderLength());
  1359  #ifndef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
  1360      aesCcm.Payload(aFrame.GetPayload(), aFrame.GetPayload(), aFrame.GetPayloadLength(), false);
  1361  #else
  1362      // for fuzz tests, execute AES but do not alter the payload
  1363      uint8_t fuzz[OT_RADIO_FRAME_MAX_SIZE];
  1364      aesCcm.Payload(fuzz, aFrame.GetPayload(), aFrame.GetPayloadLength(), false);
  1365  #endif
  1366      aesCcm.Finalize(tag, &tagLength);
  1367
  1368  #ifndef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
  1369      VerifyOrExit(memcmp(tag, aFrame.GetFooter(), tagLength) == 0, error = OT_ERROR_SECURITY);
  1370  #endif
  1371
  1372      if ((keyIdMode == Frame::kKeyIdMode1) && (aNeighbor->GetState() == Neighbor::kStateValid))
  1373      {
  1374          if (aNeighbor->GetKeySequence() != keySequence)
  1375          {
  1376              aNeighbor->SetKeySequence(keySequence);
  1377              aNeighbor->SetMleFrameCounter(0);
  1378          }
  1379
  1380          aNeighbor->SetLinkFrameCounter(frameCounter + 1);
  1381
  1382          if (keySequence > keyManager.GetCurrentKeySequence())
  1383          {
  1384              keyManager.SetCurrentKeySequence(keySequence);
  1385          }
  1386      }
  1387
  1388  exit:
